22	import java.time.Instant;
23	import java.time.LocalDate;
24	import java.util.List;
25	import java.util.Optional;
26	
27	/**
28	 * 基于 JdbcTemplate 的备案记录适配器。
29	 *
30	 * <p>所有状态竞争（公示期满 vs 异议受理、版本替代）均以带状态谓词的单条原子
31	 * UPDATE 实现，受影响行数决定唯一终态归属。</p>
32	 */
33	@Repository
34	public class JdbcFilingPort implements FilingPort {
35	
36	    private static final TypeReference<List<FormulationIngredient>> FORMULATION_TYPE = new TypeReference<>() {
37	    };
38	    private static final TypeReference<List<String>> STRING_LIST_TYPE = new TypeReference<>() {
39	    };
40	    private static final TypeReference<List<TestReportRecord>> REPORT_LIST_TYPE = new TypeReference<>() {
41	    };
42	
43	    private final JdbcTemplate jdbc;
44	
45	    public JdbcFilingPort(JdbcTemplate jdbc) {
46	        this.jdbc = jdbc;
47	    }
48	
49	    private static final RowMapper<FilingRecord> MAPPER = (rs, n) -> new FilingRecord(
50	            rs.getLong("id"),
51	            rs.getString("filing_no"),
52	            rs.getString("product_code"),
53	            rs.getString("product_name"),
54	            rs.getInt("version_no"),
55	            rs.getString("parent_filing_no"),
56	            ChangeType.valueOf(rs.getString("change_type")),
57	            FilingStatus.valueOf(rs.getString("status")),
58	            JsonSupport.fromJson(rs.getString("formulation_json"), FORMULATION_TYPE),
59	            JsonSupport.fromJson(rs.getString("claims_json"), STRING_LIST_TYPE),
60	            JsonSupport.fromJson(rs.getString("reports_json"), REPORT_LIST_TYPE),
61	            rs.getString("packaging_text"),
62	            rs.getString("request_id"),
63	            rs.getTimestamp("submitted_at_utc").toInstant(),
64	            toInstant(rs.getTimestamp("form_reviewed_at_utc")),
65	            toLocalDate(rs.getDate("public_notice_date_utc")),
66	            toInstant(rs.getTimestamp("public_expires_at_utc")),
67	            toInstant(rs.getTimestamp("objection_received_at_utc")),
68	            toInstant(rs.getTimestamp("effective_at_utc")),
69	            toInstant(rs.getTimestamp("withdrawn_at_utc")),
70	            rs.getString("reject_reason"));
71	
72	    private static final RowMapper<ReviewDetail> REVIEW_MAPPER = (rs, n) -> new ReviewDetail(
73	            rs.getLong("id"),
74	            rs.getString("filing_no"),
75	            rs.getInt("version_no"),
76	            rs.getString("stage"),
77	            rs.getString("rule_code"),
78	            rs.getInt("passed") == 1,
79	            rs.getString("detail"),
80	            rs.getTimestamp("created_at_utc").toInstant());
81	
82	    private static Instant toInstant(Timestamp ts) {
83	        return ts == null ? null : ts.toInstant();
84	    }
85	
86	    private static LocalDate toLocalDate(java.sql.Date d) {
87	        return d == null ? null : d.toLocalDate();
88	    }
89	
90	    private static void setInstant(PreparedStatement ps, int idx, Instant v) throws java.sql.SQLException {
91	        if (v == null) {
92	            ps.setNull(idx, java.sql.Types.TIMESTAMP);
93	        } else {
94	            ps.setTimestamp(idx, Timestamp.from(v));
95	        }
96	    }
97	
98	    private static void setDate(PreparedStatement ps, int idx, LocalDate v) throws java.sql.SQLException {
99	        if (v == null) {
100	            ps.setNull(idx, java.sql.Types.DATE);
101	        } else {
102	            ps.setDate(idx, java.sql.Date.valueOf(v));
103	        }
104	    }
105	
106	    private static void setString(PreparedStatement ps, int idx, String v) throws java.sql.SQLException {
107	        if (v == null) {
108	            ps.setNull(idx, java.sql.Types.VARCHAR);
109	        } else {
110	            ps.setString(idx, v);
111	        }
112	    }
113	
114	    @Override
115	    public long nextFilingSequence() {
116	        jdbc.update("UPDATE filing_sequence SET seq = seq + 1 WHERE id = 1");
117	        Long seq = jdbc.queryForObject("SELECT seq FROM filing_sequence WHERE id = 1", Long.class);
118	        if (seq == null) {
119	            throw new IllegalStateException("备案编号顺序表未初始化");
120	        }
121	        return seq;
122	    }
123	
124	    @Override
125	    public void insert(FilingRecord r) {
126	        KeyHolder keyHolder = new GeneratedKeyHolder();
127	        jdbc.update(con -> {
128	            PreparedStatement ps = con.prepareStatement("""
129	                    INSERT INTO filing_record
130	                      (filing_no, product_code, product_name, version_no, parent_filing_no,
131	                       change_type, status, formulation_json, claims_json, reports_json,
132	                       packaging_text, request_id, submitted_at_utc, form_reviewed_at_utc,
133	                       public_notice_date_utc, public_expires_at_utc, objection_received_at_utc,
134	                       effective_at_utc, withdrawn_at_utc, reject_reason,
135	                       created_at_utc, updated_at_utc)
136	                    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
137	                    """, Statement.RETURN_GENERATED_KEYS);
138	            int i = 1;
139	            setString(ps, i++, r.filingNo());
140	            ps.setString(i++, r.productCode());
141	            ps.setString(i++, r.productName());
142	            ps.setInt(i++, r.versionNo());
143	            setString(ps, i++, r.parentFilingNo());
144	            ps.setString(i++, r.changeType().name());
145	            ps.setString(i++, r.status().name());
146	            ps.setString(i++, JsonSupport.toJson(r.formulation()));
147	            ps.setString(i++, JsonSupport.toJson(r.claims()));
148	            ps.setString(i++, JsonSupport.toJson(r.reports()));
149	            setString(ps, i++, r.packagingText());
150	            ps.setString(i++, r.requestId());
151	            ps.setTimestamp(i++, Timestamp.from(r.submittedAtUtc()));
152	            setInstant(ps, i++, r.formReviewedAtUtc());
153	            setDate(ps, i++, r.publicNoticeDateUtc());
154	            setInstant(ps, i++, r.publicExpiresAtUtc());
155	            setInstant(ps, i++, r.objectionReceivedAtUtc());
156	            setInstant(ps, i++, r.effectiveAtUtc());
157	            setInstant(ps, i++, r.withdrawnAtUtc());
158	            setString(ps, i++, r.rejectReason());
159	            Instant now = Instant.now();
160	            ps.setTimestamp(i++, Timestamp.from(now));
161	            ps.setTimestamp(i, Timestamp.from(now));
162	            return ps;
163	        }, keyHolder);
164	    }
165	
166	    @Override
167	    public void update(FilingRecord r) {
168	        int updated = jdbc.update("""
169	                UPDATE filing_record SET
170	                  filing_no = ?, product_code = ?, product_name = ?, version_no = ?,
171	                  parent_filing_no = ?, change_type = ?, status = ?,
172	                  formulation_json = ?, claims_json = ?, reports_json = ?,
173	                  packaging_text = ?, request_id = ?, submitted_at_utc = ?,
174	                  form_reviewed_at_utc = ?, public_notice_date_utc = ?,
175	                  public_expires_at_utc = ?, objection_received_at_utc = ?,
176	                  effective_at_utc = ?, withdrawn_at_utc = ?, reject_reason = ?,
177	                  updated_at_utc = ?
178	                WHERE id = ?
179	                """,
180	                r.filingNo(), r.productCode(), r.productName(), r.versionNo(),
181	                r.parentFilingNo(), r.changeType().name(), r.status().name(),
182	                JsonSupport.toJson(r.formulation()), JsonSupport.toJson(r.claims()),
183	                JsonSupport.toJson(r.reports()), r.packagingText(), r.requestId(),
184	                Timestamp.from(r.submittedAtUtc()),
185	                ts(r.formReviewedAtUtc()), date(r.publicNoticeDateUtc()),
186	                ts(r.publicExpiresAtUtc()), ts(r.objectionReceivedAtUtc()),
187	                ts(r.effectiveAtUtc()), ts(r.withdrawnAtUtc()), r.rejectReason(),
188	                Timestamp.from(Instant.now()), r.id());
189	        if (updated != 1) {
190	            throw new IllegalStateException("备案版本更新失败，id=" + r.id());
191	        }
192	    }
193	
194	    private static Timestamp ts(Instant v) {
195	        return v == null ? null : Timestamp.from(v);
196	    }
197	
198	    private static java.sql.Date date(LocalDate v) {
199	        return v == null ? null : java.sql.Date.valueOf(v);
200	    }
201	
202	    @Override
203	    public Optional<FilingRecord> findById(long id) {
204	        return jdbc.query(selectAll() + " WHERE id = ?", MAPPER, id).stream().findFirst();
205	    }
206	
207	    @Override
208	    public Optional<FilingRecord> findLatestByNo(String filingNo) {
209	        return jdbc.query(selectAll() + " WHERE filing_no = ? ORDER BY version_no DESC LIMIT 1",
210	                MAPPER, filingNo).stream().findFirst();
211	    }
212	
213	    @Override
214	    public Optional<FilingRecord> findVersion(String filingNo, int versionNo) {
215	        return jdbc.query(selectAll() + " WHERE filing_no = ? AND version_no = ?",
216	                MAPPER, filingNo, versionNo).stream().findFirst();
217	    }
218	
219	    @Override
220	    public List<FilingRecord> findByProduct(String productCode) {
221	        return jdbc.query(selectAll() + " WHERE product_code = ? ORDER BY version_no ASC, id ASC",
222	                MAPPER, productCode);
223	    }
224	
225	    private static String selectAll() {
226	        return """
227	                SELECT id, filing_no, product_code, product_name, version_no, parent_filing_no,
228	                       change_type, status, formulation_json, claims_json, reports_json,
229	                       packaging_text, request_id, submitted_at_utc, form_reviewed_at_utc,
230	                       public_notice_date_utc, public_expires_at_utc, objection_received_at_utc,
231	                       effective_at_utc, withdrawn_at_utc, reject_reason
232	                FROM filing_record
233	                """;
234	    }
235	
236	    @Override
237	    public Optional<ActiveSlot> findActiveSlot(String productCode) {
238	        return jdbc.query(
239	                "SELECT product_code, filing_no, version_no, since_utc "
240	                        + "FROM product_active_filing WHERE product_code = ?",
241	                (rs, n) -> new ActiveSlot(
242	                        rs.getString("product_code"),
243	                        rs.getString("filing_no"),
244	                        rs.getInt("version_no"),
245	                        rs.getTimestamp("since_utc").toInstant()),
246	                productCode).stream().findFirst();
247	    }
248	
249	    @Override
250	    public void occupySlot(String productCode, String filingNo, int versionNo, Instant now) {
251	        jdbc.update("""
252	                INSERT INTO product_active_filing (product_code, filing_no, version_no, since_utc)
253	                VALUES (?, ?, ?, ?)
254	                """, productCode, filingNo, versionNo, Timestamp.from(now));
255	    }
256	
257	    @Override
258	    public void replaceSlot(String productCode, String filingNo, int versionNo, Instant now) {
259	        int updated = jdbc.update("""
260	                UPDATE product_active_filing
261	                SET filing_no = ?, version_no = ?, since_utc = ?
262	                WHERE product_code = ?
263	                """, filingNo, versionNo, Timestamp.from(now), productCode);
264	        if (updated != 1) {
265	            throw new IllegalStateException("有效备案槽不存在，无法切换: " + productCode);
266	        }
267	    }
268	
269	    @Override
270	    public void releaseSlot(String productCode) {
271	        jdbc.update("DELETE FROM product_active_filing WHERE product_code = ?", productCode);
272	    }
273	
274	    @Override
275	    public boolean acceptObjectionIfPublic(long id, Instant objectionAtUtc) {
276	        int updated = jdbc.update("""
277	                UPDATE filing_record
278	                SET status = 'OBJECTION_REVIEW',
279	                    objection_received_at_utc = ?,
280	                    updated_at_utc = ?
281	                WHERE id = ? AND status = 'PUBLIC'
282	                """, Timestamp.from(objectionAtUtc), Timestamp.from(Instant.now()), id);
283	        return updated == 1;
284	    }
285	
286	    @Override
287	    public boolean expireToEffectiveIfPublic(long id, Instant effectiveAtUtc) {
288	        int updated = jdbc.update("""
289	                UPDATE filing_record
290	                SET status = 'EFFECTIVE',
291	                    effective_at_utc = ?,
292	                    updated_at_utc = ?
293	                WHERE id = ? AND status = 'PUBLIC'
294	                """, Timestamp.from(effectiveAtUtc), Timestamp.from(Instant.now()), id);
295	        return updated == 1;
296	    }
297	
298	    @Override
299	    public boolean supersedeEffective(long id, Instant now) {
300	        int updated = jdbc.update("""
301	                UPDATE filing_record
302	                SET status = 'SUPERSEDED', updated_at_utc = ?
303	                WHERE id = ? AND status = 'EFFECTIVE'
304	                """, Timestamp.from(now), id);
305	        return updated == 1;
306	    }
307	
308	    @Override
309	    public void markWithdrawn(long id, Instant now, String reason) {
310	        int updated = jdbc.update("""
311	                UPDATE filing_record
312	                SET status = 'WITHDRAWN', withdrawn_at_utc = ?, reject_reason = ?, updated_at_utc = ?
313	                WHERE id = ?
314	                """, Timestamp.from(now), reason, Timestamp.from(Instant.now()), id);
315	        if (updated != 1) {
316	            throw new IllegalStateException("注销状态更新失败，id=" + id);
317	        }
318	    }
319	
320	    @Override
321	    public void markRejectedAfterObjection(long id, Instant now, String reason) {
322	        int updated = jdbc.update("""
323	                UPDATE filing_record
324	                SET status = 'REJECTED_AFTER_OBJECTION', reject_reason = ?, updated_at_utc = ?
325	                WHERE id = ?
326	                """, reason, Timestamp.from(Instant.now()), id);
327	        if (updated != 1) {
328	            throw new IllegalStateException("异议驳回状态更新失败，id=" + id);
329	        }
330	    }
331	
332	    @Override
333	    public void reopenPublic(long id) {
334	        int updated = jdbc.update("""
335	                UPDATE filing_record SET status = 'PUBLIC', updated_at_utc = ?
336	                WHERE id = ? AND status = 'OBJECTION_REVIEW'
337	                """, Timestamp.from(Instant.now()), id);
338	        if (updated != 1) {
339	            throw new IllegalStateException("异议不成立回到公示失败，id=" + id);
340	        }
341	    }
342	
343	    @Override
344	    public void saveReviews(List<ReviewDetail> details) {
345	        if (details.isEmpty()) {
346	            return;
347	        }
348	        jdbc.batchUpdate("""
349	                INSERT INTO review_detail
350	                  (filing_no, version_no, stage, rule_code, passed, detail, created_at_utc)
351	                VALUES (?, ?, ?, ?, ?, ?, ?)
352	                """,
353	                details, details.size(), (ps, d) -> {
354	                    ps.setString(1, d.filingNo());
