1	package com.example.starter.cosmetic.web;
2	
3	import com.example.starter.cosmetic.service.ConflictException;
4	import com.example.starter.cosmetic.service.NotFoundException;
5	import org.springframework.dao.DataIntegrityViolationException;
6	import org.springframework.http.HttpStatus;
7	import org.springframework.http.ResponseEntity;
8	import org.springframework.web.bind.MethodArgumentNotValidException;
9	import org.springframework.web.bind.annotation.ExceptionHandler;
10	import org.springframework.web.bind.annotation.RestControllerAdvice;
11	
12	import java.time.Instant;
13	import java.util.Map;
14	
15	/**
16	 * 统一异常到 HTTP 状态的映射：404 不存在，409 业务冲突（含同键异参），400 参数非法。
17	 */
18	@RestControllerAdvice
19	public class GlobalExceptionHandler {
20	
21	    /** 404。 */
22	    @ExceptionHandler(NotFoundException.class)
23	    public ResponseEntity<Map<String, Object>> handleNotFound(NotFoundException e) {
24	        return ResponseEntity.status(HttpStatus.NOT_FOUND).body(body("NOT_FOUND", e.getMessage()));
25	    }
26	
27	    /** 409。 */
28	    @ExceptionHandler(ConflictException.class)
29	    public ResponseEntity<Map<String, Object>> handleConflict(ConflictException e) {
30	        return ResponseEntity.status(HttpStatus.CONFLICT).body(body(e.code(), e.getMessage()));
31	    }
32	
33	    /** 400 参数校验。 */
34	    @ExceptionHandler(MethodArgumentNotValidException.class)
35	    public ResponseEntity<Map<String, Object>> handleValidation(MethodArgumentNotValidException e) {
36	        String message = e.getBindingResult().getFieldErrors().stream()
37	                .map(fe -> fe.getField() + ": " + fe.getDefaultMessage())
38	                .findFirst()
39	                .orElse("参数校验失败");
40	        return ResponseEntity.badRequest().body(body("VALIDATION_FAILED", message));
41	    }
42	
43	    /** 400 其他非法参数。 */
44	    @ExceptionHandler(IllegalArgumentException.class)
45	    public ResponseEntity<Map<String, Object>> handleIllegalArg(IllegalArgumentException e) {
46	        return ResponseEntity.badRequest().body(body("INVALID_ARGUMENT", e.getMessage()));
47	    }
48	
49	    /**
50	     * 409 数据约束冲突：并发下的幂等键/版本/有效槽唯一竞争等。
51	     */
52	    @ExceptionHandler(DataIntegrityViolationException.class)
53	    public ResponseEntity<Map<String, Object>> handleDataIntegrity(DataIntegrityViolationException e) {
54	        return ResponseEntity.status(HttpStatus.CONFLICT)
55	                .body(body("DATA_INTEGRITY_CONFLICT", "并发数据冲突，请重试"));
56	    }
