                EFFICACY_MAPPER, code).stream().findFirst();
    }

    @Override
    public List<EfficacyCatalog> listEfficacies() {
        return jdbc.query("SELECT code, name, special, supported FROM efficacy_catalog ORDER BY code",
                EFFICACY_MAPPER);
