package com.example.starter.cosmetic.child.domain;

/**
 * 儿童备案聚合状态。
 *
 * <p>流转：提交/补正后同步审查，通过则 IN_PUBLICITY（受理并公示），
 * 不通过则 REVIEW_REJECTED（零生效，可补正）；公示期满 EFFECTIVE。</p>
 */
public enum ChildFilingStatus {

    /** 审查不通过（零生效）：缺项已一次列全，可材料补正生成新修订。 */
    REVIEW_REJECTED,
    /** 公示中：最新修订已受理并冻结，公示只能使用该最新修订。 */
    IN_PUBLICITY,
    /** 生效：当前最新修订已生效。 */
    EFFECTIVE
}

package com.example.starter.cosmetic.child.domain;

/**
 * 儿童备案修订状态。
 */
public enum ChildRevisionStatus {

    /** 审查不通过（零生效）：缺项一次列全，等待补正。 */
    REJECTED,
    /** 公示中：受理时已冻结报告清单、分龄规则版本与标识文本摘要。 */
    PUBLIC,
    /** 已被新修订取代：补正使旧修订待审批准失效（终态）。 */
    INVALIDATED,
    /** 生效：公示期满或简易变更即时生效。 */
    EFFECTIVE,
    /** 已被生效的新修订替代（终态）。 */
    SUPERSEDED
}

package com.example.starter.cosmetic.child.domain;

/**
 * 儿童备案修订类型。
 */
public enum ChildRevisionType {

    /** 首次提交。 */
    INITIAL,
    /** 材料补正：生成新修订并使旧修订待审批准失效。 */
    CORRECTION,
    /** 实质变更：儿童属性、年龄或标识适用范围等变化，重新审查并公示。 */
    SUBSTANTIVE,
    /** 简易变更：仅包装文字类调整，即时生效。 */
    SIMPLE
}

package com.example.starter.cosmetic.child.domain;

/**
 * 分龄档位（整数月闭区间）。
 *
 * @param bandCode    档位编码：BAND_0_36 / BAND_37_144
 * @param lowerMonths 档位下限（整数月，含）
 * @param upperMonths 档位上限（整数月，含）
 */
public record AgeBand(String bandCode, int lowerMonths, int upperMonths) {

    /** 低龄档（0~36月）档位编码。 */
    public static final String BAND_LOW = "BAND_0_36";
    /** 高龄档（37~144月）档位编码。 */
    public static final String BAND_HIGH = "BAND_37_144";

    /** 申请年龄范围 [lower, upper] 是否落入/触及本档。 */
    public boolean intersects(int lower, int upper) {
        return lower <= upperMonths && upper >= lowerMonths;
    }

    /** 申请年龄范围与本档的交集下界（整数月，含）。 */
    public int segmentLower(int lower) {
        return Math.max(lower, lowerMonths);
    }

    /** 申请年龄范围与本档的交集上界（整数月，含）。 */
    public int segmentUpper(int upper) {
        return Math.min(upper, upperMonths);
    }
}

package com.example.starter.cosmetic.child.domain;

import java.util.List;

/**
 * 分龄规则版本（合成初始化，受理时随修订冻结）。
 *
 * @param ruleVersion 规则版本号
 * @param bands       档位列表（0~36月、37~144月）
 */
public record ChildAgeRule(String ruleVersion, List<AgeBand> bands) {

    /** 申请年龄范围 [lower, upper] 触及的全部档位（跨档返回两档）。 */
    public List<AgeBand> requiredBands(int lower, int upper) {
        return bands.stream().filter(b -> b.intersects(lower, upper)).toList();
    }
}

