                List.of(lowBandReport("SR-" + requestId)), List.of(lowBandLabel()),
                "包装：置于婴幼儿不可触及处", null);
    }

    /** 跨档（0~144月）材料齐备的儿童备案提交。 */
    public static ChildSubmitRequest crossBandSubmit(String requestId, String productCode) {
