                                 "safetyReports": [
                                   {"reportNo": "SR-C2-L", "bandCode": "BAND_0_36",
                                    "coverLowerMonths": 0, "coverUpperMonths": 36},
                                   {"reportNo": "SR-C2-H", "bandCode": "BAND_37_144",
                                    "coverLowerMonths": 37, "coverUpperMonths": 144}
